[
  {
    "statement": "Key disease prevention practices for aquaculture are applicable to tilapia farming.",
    "citations": []
  },
  {
    "statement": "Using probiotics and immunostimulants in fish feed can boost immune response and reduce parasite infections.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Implementing vaccination programs for fish has shown increased survival rates against various bacterial diseases.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Adding salt to ponds helps to prevent fungal infections in fish.",
    "citations": [
      "762"
    ]
  },
  {
    "statement": "Implementing biosecurity measures, including quarantine protocols for new stock, is a key disease prevention practice.",
    "citations": [
      "2156",
      "3082"
    ]
  },
  {
    "statement": "Preventing biofouling through regular cleaning and maintenance of culture systems is a recommended practice.",
    "citations": [
      "2162"
    ]
  },
  {
    "statement": "Sourcing fish stock from disease-free hatcheries is a recommended practice.",
    "citations": [
      "2159"
    ]
  },
  {
    "statement": "Most disease prevention interventions for aquaculture lack specific studies evaluating the interventions' effects on tilapia.",
    "citations": []
  },
  {
    "statement": "Many studies report finding no research that directly evaluated the effectiveness of certain disease prevention interventions on tilapia.",
    "citations": []
  }
]

[
  {
    "statement": "Vaccinations appear to have more substantial evidence supporting improved salmon survival rates.",
    "citations": []
  },
  {
    "statement": "Multiple controlled studies from Iceland, Norway, Australia, and Canada have shown that vaccinations against specific diseases increase salmon survival rates.",
    "citations": []
  },
  {
    "statement": "Vaccinations increase survival rates for salmon after exposure to various disease-causing bacteria.",
    "citations": []
  },
  {
    "statement": "Disease-causing bacteria that affect salmon include Aeromonas salmonicida spp.achromogenes, Yersinia ruckeri, marine flexibacteriosis, bacterial kidney disease, and infectious salmon anaemia.",
    "citations": []
  },
  {
    "statement": "Altering cage size has only limited evidence showing it reduces levels of amoebic gill disease.",
    "citations": []
  },
  {
    "statement": "One replicated study from Australia showed reduced levels of amoebic gill disease in larger cages compared to smaller cages.",
    "citations": []
  }
]

[
  {
    "statement": "Research has been conducted on the use of genetically modified ingredients in salmon feed.",
    "citations": []
  },
  {
    "statement": "Three controlled, replicated studies in Norway found no difference in the growth rate of Atlantic salmon that were fed diets containing either GM or non-GM soybeans.",
    "citations": []
  },
  {
    "statement": "A randomised, replicated, controlled study in Norway found no differences in the histology of fish fed diets containing either GM or non-GM soybeans.",
    "citations": []
  },
  {
    "statement": "Plant-based protein sources are being used as alternative protein sources in salmon feed.",
    "citations": []
  },
  {
    "statement": "Plant-based protein sources used in salmon feed may include GM ingredients.",
    "citations": []
  },
  {
    "statement": "Six studies in Norway, Scotland and the USA found that the inclusion of plant-based proteins within feed led to decreased growth rates in salmon compared to fish meal diets.",
    "citations": []
  },
  {
    "statement": "The action documents do not contain specific information about international regulatory frameworks for GM ingredients in salmon feed.",
    "citations": []
  },
  {
    "statement": "The action documents do not contain specific information about approval processes for GM ingredients in salmon feed.",
    "citations": []
  }
]
